package com.freshmart.catalog;
import java.sql.Timestamp;import java.time.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:catalog;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.datasource.username=sa","spring.datasource.password=","app.token-secret=catalog-test-only-randomizable-secret-123456789","app.secure-cookies=false"})
@AutoConfigureMockMvc
class CatalogIntegrationTest {
 @Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired CatalogService service;
 @BeforeEach void seed(){
  jdbc.update("DELETE FROM fm_inventory_batch");jdbc.update("DELETE FROM fm_sku");jdbc.update("DELETE FROM fm_product");jdbc.update("DELETE FROM fm_category");
  jdbc.update("INSERT INTO fm_category(category_id,code,name,short_name,image_url,sort_order,enabled) VALUES('fruit','FRUIT','水果','果','http://localhost:8080/catalog/fruit.jpg',1,true),('hidden','HIDDEN','隐藏','隐','http://localhost:8080/catalog/hidden.jpg',2,false)");
  product("apple","fruit","苹果","ON_SALE");product("pear","fruit","梨","ON_SALE");product("sold","fruit","缺货商品","ON_SALE");product("draft","fruit","草稿","DRAFT");product("disabled-category","hidden","隐藏分类商品","ON_SALE");product("no-sku","fruit","无规格商品","ON_SALE");
  sku("apple-sku","apple",1000,980,"GRAM",500L);sku("pear-sku","pear",600,580,"PIECE",null);sku("sold-sku","sold",300,280,"PIECE",null);sku("draft-sku","draft",100,90,"PIECE",null);sku("hidden-sku","disabled-category",100,90,"PIECE",null);
  batch("apple-fresh","apple-sku",10000,1000,0,8,"NORMAL");batch("apple-near","apple-sku",2000,0,0,2,"NORMAL");batch("pear-expired","pear-sku",100,0,0,-1,"NORMAL");batch("pear-isolated","pear-sku",100,0,100,1,"QUARANTINED");batch("pear-held","pear-sku",100,100,0,1,"NORMAL");batch("pear-good","pear-sku",3,0,0,10,"NORMAL");batch("sold-expired","sold-sku",50,0,0,-1,"NORMAL");
 }
 void product(String id,String category,String name,String status){jdbc.update("INSERT INTO fm_product(product_id,spu_code,category_id,name,description,origin,storage,image_url,status,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",id,"SPU-"+id,category,name,"真实测试说明","山东","COLD","http://localhost:8080/catalog/"+id+".jpg",status);}
 void sku(String id,String product,long price,long member,String base,Long grams){jdbc.update("INSERT INTO fm_sku(sku_id,sku_code,product_id,name,unit_label,base_unit,price_mode,price_unit_gram,price,member_price,image_url,status,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'ACTIVE',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",id,"SKU-"+id,product,"标准规格",grams==null?"件":"500g",base,grams==null?"BY_PIECE":"BY_WEIGHT",grams,price,member,"http://localhost:8080/catalog/"+id+".jpg");}
 void batch(String id,String sku,long onhand,long reserved,long quarantined,int days,String lifecycle){jdbc.update("INSERT INTO fm_inventory_batch(batch_id,sku_id,batch_no,warehouse_id,received_at,expires_at,lifecycle_status,on_hand,reserved,quarantined,version,created_at,updated_at) VALUES(?,?,?,'warehouse',?,?,?,?,?,?,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",id,sku,id,Timestamp.from(Instant.now().minusSeconds(259200)),Timestamp.from(Instant.now().plusSeconds(days*86400L)),lifecycle,onhand,reserved,quarantined);}
 @Test void publicListingHidesDraftDisabledCategoriesAndMissingSkus()throws Exception{mvc.perform(get("/api/v1/products")).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(3)).andExpect(jsonPath("$.data.items.length()").value(3));mvc.perform(get("/api/v1/categories")).andExpect(jsonPath("$.data.items.length()").value(1));for(String id:new String[]{"draft","disabled-category","no-sku","unknown"})mvc.perform(get("/api/v1/products/"+id)).andExpect(status().isNotFound());}
 @Test void freshnessUsesAvailableNormalUnexpiredFefoAndDoesNotExposeBatchLedger()throws Exception{
  var apple=service.product("apple");assertEquals(900,apple.salePrice());assertTrue(apple.nearExpiry());assertEquals("NEAR_EXPIRY",apple.freshness());assertEquals("IN_STOCK",apple.stockStatus());assertEquals(500,apple.skus().getFirst().priceUnitGram());
  var pear=service.product("pear");assertFalse(pear.nearExpiry());assertEquals(580,pear.salePrice());assertEquals("LOW",pear.stockStatus());assertEquals("SOLD_OUT",service.product("sold").stockStatus());assertNull(service.product("sold").freshness());
  var r=mvc.perform(get("/api/v1/products/apple")).andExpect(status().isOk()).andReturn();for(String secret:new String[]{"batchId","batchNo","onHand","reserved","quarantined","warehouseId"})assertFalse(r.getResponse().getContentAsString().contains(secret));
 }
 @Test void filtersPagingAndPriceSortUseDatabaseValues()throws Exception{
  mvc.perform(get("/api/v1/products").param("nearExpiry","true")).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(1)).andExpect(jsonPath("$.data.items[0].productId").value("apple"));
  mvc.perform(get("/api/v1/products").param("sort","PRICE_ASC").param("size","1").param("page","2")).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(3)).andExpect(jsonPath("$.data.items[0].productId").value("pear"));
  mvc.perform(get("/api/v1/products").param("keyword","' OR 1=1 --")).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(0));
  mvc.perform(get("/api/v1/products").param("keyword","苹果")).andExpect(jsonPath("$.data.items[0].productId").value("apple"));
 }
 @Test void malformedQueryIsReal400AndEmptyPageIsHonest()throws Exception{for(String[] pair:new String[][]{{"page","x"},{"page","0"},{"size","101"},{"sort","price;drop"},{"nearExpiry","unknown"}})mvc.perform(get("/api/v1/products").param(pair[0],pair[1])).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/products").param("page","99")).andExpect(status().isOk()).andExpect(jsonPath("$.data.items.length()").value(0)).andExpect(jsonPath("$.data.total").value(3));}
 @Test void homeAndReviewsOnlyReturnStoredCatalogAndActualEmptyReviewSet()throws Exception{mvc.perform(get("/api/v1/home")).andExpect(status().isOk()).andExpect(jsonPath("$.data.banners.length()").value(0)).andExpect(jsonPath("$.data.recommendedProducts.length()").value(3)).andExpect(jsonPath("$.data.nearExpiryProducts.length()").value(1));mvc.perform(get("/api/v1/products/apple/reviews")).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(0)).andExpect(jsonPath("$.data.items.length()").value(0));}
}
